      +   '<div class="chip-row" id="nvTipo">'
      +     TIPOS.map(function(t,i){ return '<button type="button" class="chip" data-tipo="'+t[0]+'" aria-pressed="'+(i===0?"true":"false")+'">'+t[1]+'</button>'; }).join("")
      +   '</div>'
      +   '<div class="grid2" style="margin-top:12px;">'
      +     '<label class="f"><span>Data</span><input type="date" id="nvData" /></label>'
